#include <stdio.h>
#include <stdlib.h>

// Define the stock and price arrays
long stock[5];
long price[5];

int main(int argc, char **argv) {
    // Initialize the stock and price arrays
    for (int i = 0; i < 5; i++) {
        stock[i] = 0;
        price[i] = 0;
    }

    long revenue = 0;
    int op_count = (argc - 1) / 3;

    for (int i = 0; i < op_count; i++) {
        char op = *argv[i * 3 + 1];
        int sku = atoi(argv[i * 3 + 2]);
        int qty = atoi(argv[i * 3 + 3]);

        if (op == 'R') {
            // Restock operation
            stock[sku] += qty;
            printf("RESTOCK sku=%d qty=%d\n", sku, qty);
        } else if (op == 'S') {
            // Sell operation
            if (stock[sku] >= qty) {
                stock[sku] -= qty;
                revenue += price[sku] * qty;
                printf("SELL sku=%d qty=%d revenue+=%ld\n", sku, qty, price[sku] * qty);
            } else {
                printf("INSUFFICIENT_STOCK sku=%d\n", sku);
            }
        }
    }

    // Print the final stock and revenue
    printf("FINAL stock=");
    for (int i = 0; i < 5; i++) {
        printf("%ld", stock[i]);
        if (i < 4) printf(",");
    }
    printf(" revenue=%ld\n", revenue);

    return 0;
}
